INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$fc2bcc79$SATQ$, $SATQ$20085733-830c-480a-8032-c336efd01462$SATQ$::uuid, $SATQ$163b82cb-d0ab-4a4c-bfc4-0881de956ecf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Tyrian purple was a highly prized dye among the Phoenicians (an ancient civilization located in present-day Lebanon). The Phoenicians were famous for using this natural dye to color their clothes a distinctive purple. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the name &ldquo;Phoenicia&rdquo; itself, some historians claim, may have originally meant &ldquo;land of purple.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"035a2a62-8d04-4cab-9075-83ed6ebf8822","content":"<p>In fact,</p>"},{"id":"1a75ae43-fbe1-4d5f-a73c-e00c6521c034","content":"<p>Regardless,</p>"},{"id":"fd199c3a-c093-4ad9-a2c0-5838c674d1d5","content":"<p>Lastly,</p>"},{"id":"10719597-95f1-454a-b0cb-233e0f7e2072","content":"<p>On the contrary,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["035a2a62-8d04-4cab-9075-83ed6ebf8822"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. &ldquo;In fact&rdquo; logically signals that the claim in this sentence&mdash;Phoenicia being named after the color purple&mdash;emphasizes and supports the previous claim that Phoenicians were famous for using purple dye. </p><p>Choice B is incorrect because &ldquo;regardless&rdquo; illogically signals that the claim about Phoenicia&rsquo;s name contrasts with the previous claim that Phoenicians were famous for using purple dye. Instead, the naming emphasizes and supports this claim. Choice C is incorrect because &ldquo;lastly&rdquo; illogically signals that the claim about Phoenicia&rsquo;s name is the final step in a process or sequence. Instead, the naming emphasizes and supports the previous claim that Phoenicians were famous for using purple dye. Choice D is incorrect because &ldquo;on the contrary&rdquo; illogically signals that the claim about Phoenicia&rsquo;s name directly opposes the previous claim that Phoenicians were famous for using purple dye. Instead, the naming emphasizes and supports this claim. </p>$SATQ$, false, 0, $SATQ$OSP-243-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$fb967926-4e57-4bf3-9df7-1a3f66e5b9a8$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"fc2bcc79","external_id":"20085733-830c-480a-8032-c336efd01462","vaultid":"163b82cb-d0ab-4a4c-bfc4-0881de956ecf","uId":"27ef1c14-147e-4db6-96a4-d8f1afdf8fb1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Tyrian purple was a highly prized dye among the Phoenicians (an ancient civilization located in present-day Lebanon). The Phoenicians were famous for using this natural dye to color their clothes a distinctive purple. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the name &ldquo;Phoenicia&rdquo; itself, some historians claim, may have originally meant &ldquo;land of purple.&rdquo;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"035a2a62-8d04-4cab-9075-83ed6ebf8822","content":"<p>In fact,</p>"},{"id":"1a75ae43-fbe1-4d5f-a73c-e00c6521c034","content":"<p>Regardless,</p>"},{"id":"fd199c3a-c093-4ad9-a2c0-5838c674d1d5","content":"<p>Lastly,</p>"},{"id":"10719597-95f1-454a-b0cb-233e0f7e2072","content":"<p>On the contrary,</p>"}],"keys":["035a2a62-8d04-4cab-9075-83ed6ebf8822"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. &ldquo;In fact&rdquo; logically signals that the claim in this sentence&mdash;Phoenicia being named after the color purple&mdash;emphasizes and supports the previous claim that Phoenicians were famous for using purple dye. </p><p>Choice B is incorrect because &ldquo;regardless&rdquo; illogically signals that the claim about Phoenicia&rsquo;s name contrasts with the previous claim that Phoenicians were famous for using purple dye. Instead, the naming emphasizes and supports this claim. Choice C is incorrect because &ldquo;lastly&rdquo; illogically signals that the claim about Phoenicia&rsquo;s name is the final step in a process or sequence. Instead, the naming emphasizes and supports the previous claim that Phoenicians were famous for using purple dye. Choice D is incorrect because &ldquo;on the contrary&rdquo; illogically signals that the claim about Phoenicia&rsquo;s name directly opposes the previous claim that Phoenicians were famous for using purple dye. Instead, the naming emphasizes and supports this claim. </p>","parenttemplatename":"OSP-243-TRA","parenttemplateid":"","templateclusterid":"fb967926-4e57-4bf3-9df7-1a3f66e5b9a8","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$fc5e83cc$SATQ$, $SATQ$a21525d8-a5d1-4365-9eec-f6739e2dc257$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>When following musical scores, professional opera singers like soprano Ana Mar&iacute;a Mart&iacute;nez take vocal directions from descriptive notations, typically in Italian, that appear alongside the musical notes. <span aria-hidden="true">______</span><span class="sr-only">blank</span> these descriptive terms might guide the performer to sing <span lang="it"><em>giocoso</em></span> (playfully) or <span lang="it"><em>lento</em></span> (at a slow tempo).</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"6a00036c-e5b2-431b-8beb-cbf117389a73","content":"<p>On the other hand,</p>"},{"id":"d81ee6cd-a096-4ad8-8489-ffbf73b396ad","content":"<p>All the same,</p>"},{"id":"6999527f-abb0-456b-9416-a06d823dbf57","content":"<p>For example,</p>"},{"id":"f7a5ffe4-501e-4c81-8900-98ea14257b84","content":"<p>In the second place,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["6999527f-abb0-456b-9416-a06d823dbf57"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "For example" logically signals that this sentence supports the previous information about the descriptive notations opera singers use by providing specific examples of these notations: <span lang="it"><em>giocoso</em></span> (playfully) and <span lang="it"><em>lento</em></span> (at a slow tempo).</p><p>Choice A is incorrect because "on the other hand" illogically signals that the information in this sentence contrasts with the previous information about the descriptive notations opera singers use. Instead, the sentence provides examples of these notations. Choice B is incorrect because "all the same" illogically signals that the information in this sentence is true despite the previous information about the descriptive notations opera singers use. Instead, the sentence provides examples of these notations. Choice D is incorrect because "in the second place" illogically signals that the information in this sentence is a second point that is separate from the previous information about the descriptive notations opera singers use. Instead, the sentence provides examples of these notations.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"fc5e83cc","external_id":"a21525d8-a5d1-4365-9eec-f6739e2dc257","vaultid":null,"uId":"5cf835d5-3f43-4fef-8511-1cee42389105","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>When following musical scores, professional opera singers like soprano Ana Mar&iacute;a Mart&iacute;nez take vocal directions from descriptive notations, typically in Italian, that appear alongside the musical notes. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> these descriptive terms might guide the performer to sing <span lang=\"it\"><em>giocoso</em></span> (playfully) or <span lang=\"it\"><em>lento</em></span> (at a slow tempo).</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"6a00036c-e5b2-431b-8beb-cbf117389a73","content":"<p>On the other hand,</p>"},{"id":"d81ee6cd-a096-4ad8-8489-ffbf73b396ad","content":"<p>All the same,</p>"},{"id":"6999527f-abb0-456b-9416-a06d823dbf57","content":"<p>For example,</p>"},{"id":"f7a5ffe4-501e-4c81-8900-98ea14257b84","content":"<p>In the second place,</p>"}],"keys":["6999527f-abb0-456b-9416-a06d823dbf57"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"For example\" logically signals that this sentence supports the previous information about the descriptive notations opera singers use by providing specific examples of these notations: <span lang=\"it\"><em>giocoso</em></span> (playfully) and <span lang=\"it\"><em>lento</em></span> (at a slow tempo).</p><p>Choice A is incorrect because \"on the other hand\" illogically signals that the information in this sentence contrasts with the previous information about the descriptive notations opera singers use. Instead, the sentence provides examples of these notations. Choice B is incorrect because \"all the same\" illogically signals that the information in this sentence is true despite the previous information about the descriptive notations opera singers use. Instead, the sentence provides examples of these notations. Choice D is incorrect because \"in the second place\" illogically signals that the information in this sentence is a second point that is separate from the previous information about the descriptive notations opera singers use. Instead, the sentence provides examples of these notations.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$fc95a352$SATQ$, $SATQ$f830b98a-f26c-4665-9abb-e89265908b38$SATQ$::uuid, $SATQ$d650f7cb-aef8-43c6-8b21-8c79b3bfee00$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>When designing costumes for film, American artist Suttirat Larlarb typically custom fits the garments to each actor. <span aria-hidden="true">______</span><span class="sr-only">blank</span> for the film <em>Sunshine</em>, in which astronauts must reignite a dying Sun, she designed a golden spacesuit and had a factory reproduce it in a few standard sizes; lacking a tailor-made quality, the final creations reflected the ungainliness of actual spacesuits.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"7a753ece-b8c9-4e1a-a26b-c295dff7417f","content":"<p>Nevertheless,</p>"},{"id":"fdb5bbeb-4c7b-481c-ae5c-cda4b1152c9f","content":"<p>Thus,</p>"},{"id":"66aae803-0930-441a-8202-2f5be250b20f","content":"<p>Likewise,</p>"},{"id":"476a0c87-82d7-4b5e-9d2a-03c5fcf6953b","content":"<p>Moreover,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["7a753ece-b8c9-4e1a-a26b-c295dff7417f"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. &ldquo;Nevertheless&rdquo; logically signals that the information in this sentence&mdash;that the spacesuits Suttirat Larlarb designed for the film <em>Sunshine</em> were made in standard sizes in a factory&mdash;presents a notable exception to Larlarb&rsquo;s typical approach of custom-fitting garments to actors, which is described in the previous sentence.&nbsp;</p><p>Choice B is incorrect because &ldquo;thus&rdquo; illogically signals that the information in this sentence is a result or consequence of the previous information about Larlarb&rsquo;s typical approach of custom-fitting garments to actors. Instead, it presents a notable exception to Larlarb&rsquo;s typical approach. Choice C is incorrect because &ldquo;likewise&rdquo; illogically signals that the information in this sentence is similar to the previous information about Larlarb&rsquo;s typical approach of custom-fitting garments to actors. Instead, it presents a notable exception to Larlarb&rsquo;s typical approach. Choice D is incorrect because &ldquo;moreover&rdquo; illogically signals that the information in this sentence merely adds to the previous information about Larlarb&rsquo;s typical approach of custom-fitting garments to actors. Instead, it presents a notable exception to Larlarb&rsquo;s typical approach.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-222-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$96a02f32-3225-4fbe-9be7-9790c557a6a7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"fc95a352","external_id":"f830b98a-f26c-4665-9abb-e89265908b38","vaultid":"d650f7cb-aef8-43c6-8b21-8c79b3bfee00","uId":"e0752f42-bdef-4742-9a68-40fba4c833a6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>When designing costumes for film, American artist Suttirat Larlarb typically custom fits the garments to each actor. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> for the film <em>Sunshine</em>, in which astronauts must reignite a dying Sun, she designed a golden spacesuit and had a factory reproduce it in a few standard sizes; lacking a tailor-made quality, the final creations reflected the ungainliness of actual spacesuits.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"7a753ece-b8c9-4e1a-a26b-c295dff7417f","content":"<p>Nevertheless,</p>"},{"id":"fdb5bbeb-4c7b-481c-ae5c-cda4b1152c9f","content":"<p>Thus,</p>"},{"id":"66aae803-0930-441a-8202-2f5be250b20f","content":"<p>Likewise,</p>"},{"id":"476a0c87-82d7-4b5e-9d2a-03c5fcf6953b","content":"<p>Moreover,</p>"}],"keys":["7a753ece-b8c9-4e1a-a26b-c295dff7417f"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. &ldquo;Nevertheless&rdquo; logically signals that the information in this sentence&mdash;that the spacesuits Suttirat Larlarb designed for the film <em>Sunshine</em> were made in standard sizes in a factory&mdash;presents a notable exception to Larlarb&rsquo;s typical approach of custom-fitting garments to actors, which is described in the previous sentence.&nbsp;</p><p>Choice B is incorrect because &ldquo;thus&rdquo; illogically signals that the information in this sentence is a result or consequence of the previous information about Larlarb&rsquo;s typical approach of custom-fitting garments to actors. Instead, it presents a notable exception to Larlarb&rsquo;s typical approach. Choice C is incorrect because &ldquo;likewise&rdquo; illogically signals that the information in this sentence is similar to the previous information about Larlarb&rsquo;s typical approach of custom-fitting garments to actors. Instead, it presents a notable exception to Larlarb&rsquo;s typical approach. Choice D is incorrect because &ldquo;moreover&rdquo; illogically signals that the information in this sentence merely adds to the previous information about Larlarb&rsquo;s typical approach of custom-fitting garments to actors. Instead, it presents a notable exception to Larlarb&rsquo;s typical approach.&nbsp;</p>","parenttemplatename":"OSP-222-TRA","parenttemplateid":"","templateclusterid":"96a02f32-3225-4fbe-9be7-9790c557a6a7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959332,"updateDate":1691007959332}$SATQ$::jsonb, 1691007959332, 1691007959332),
    ($SATQ$fd24f48f$SATQ$, $SATQ$97d2384c-d243-41cf-b968-fe81df7675a7$SATQ$::uuid, $SATQ$58d45286-944f-4263-ba25-7caa9150103f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Before California&rsquo;s 1911 election to approve a proposition granting women the right to vote, activists across the state sold tea to promote the cause of suffrage. In San Francisco, the Woman&rsquo;s Suffrage Party sold Equality Tea at local fairs. <span aria-hidden="true">______</span><span class="sr-only">blank</span> in Los Angeles, activist Nancy Tuttle Craig, who ran one of California&rsquo;s largest grocery store firms, distributed Votes for Women Tea.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"ff68a0f5-3a22-48af-a1b5-16d4667d02a9","content":"<p>For example,</p>"},{"id":"b2722964-54a5-4471-8a66-14354a1d5c70","content":"<p>To conclude,</p>"},{"id":"75130a79-3462-424b-9395-6047b475b7ec","content":"<p>Similarly,</p>"},{"id":"98f225b7-7037-4ee8-a0e1-9eae322612f5","content":"<p>In other words,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["75130a79-3462-424b-9395-6047b475b7ec"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;Similarly&rdquo; logically signals that the activity described in this sentence (Nancy Tuttle Craig distributing Votes for Women Tea in her Los Angeles grocery stores) is like the activity described in the previous sentence (the Woman&rsquo;s Suffrage Party selling Equality Tea at fairs in San Francisco). Together, the two examples support the preceding claim that &ldquo;activists across the state sold tea to promote the cause of suffrage.&rdquo; </p><p>Choice A is incorrect because &ldquo;for example&rdquo; illogically signals that the activity described in this sentence exemplifies the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women&rsquo;s right to vote. Choice B is incorrect because &ldquo;to conclude&rdquo; illogically signals that the activity described in this sentence concludes or summarizes the information in the previous sentences. Instead, the activity is similar to the one described in the previous sentence, and both support the preceding claim about selling tea to promote women&rsquo;s right to vote. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the activity described in this sentence paraphrases the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women&rsquo;s right to vote. </p>$SATQ$, false, 0, $SATQ$OSP-220-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$b01d7e12-1be9-4cd0-b0d9-a8f8d660108b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"fd24f48f","external_id":"97d2384c-d243-41cf-b968-fe81df7675a7","vaultid":"58d45286-944f-4263-ba25-7caa9150103f","uId":"314298b6-7fe2-4093-8ee3-5b4857239807","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Before California&rsquo;s 1911 election to approve a proposition granting women the right to vote, activists across the state sold tea to promote the cause of suffrage. In San Francisco, the Woman&rsquo;s Suffrage Party sold Equality Tea at local fairs. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in Los Angeles, activist Nancy Tuttle Craig, who ran one of California&rsquo;s largest grocery store firms, distributed Votes for Women Tea.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"ff68a0f5-3a22-48af-a1b5-16d4667d02a9","content":"<p>For example,</p>"},{"id":"b2722964-54a5-4471-8a66-14354a1d5c70","content":"<p>To conclude,</p>"},{"id":"75130a79-3462-424b-9395-6047b475b7ec","content":"<p>Similarly,</p>"},{"id":"98f225b7-7037-4ee8-a0e1-9eae322612f5","content":"<p>In other words,</p>"}],"keys":["75130a79-3462-424b-9395-6047b475b7ec"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;Similarly&rdquo; logically signals that the activity described in this sentence (Nancy Tuttle Craig distributing Votes for Women Tea in her Los Angeles grocery stores) is like the activity described in the previous sentence (the Woman&rsquo;s Suffrage Party selling Equality Tea at fairs in San Francisco). Together, the two examples support the preceding claim that &ldquo;activists across the state sold tea to promote the cause of suffrage.&rdquo; </p><p>Choice A is incorrect because &ldquo;for example&rdquo; illogically signals that the activity described in this sentence exemplifies the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women&rsquo;s right to vote. Choice B is incorrect because &ldquo;to conclude&rdquo; illogically signals that the activity described in this sentence concludes or summarizes the information in the previous sentences. Instead, the activity is similar to the one described in the previous sentence, and both support the preceding claim about selling tea to promote women&rsquo;s right to vote. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the activity described in this sentence paraphrases the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women&rsquo;s right to vote. </p>","parenttemplatename":"OSP-220-TRA","parenttemplateid":"","templateclusterid":"b01d7e12-1be9-4cd0-b0d9-a8f8d660108b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959332,"updateDate":1691007959332}$SATQ$::jsonb, 1691007959332, 1691007959332),
    ($SATQ$fdd9a360$SATQ$, $SATQ$e1a88e15-d0ab-4fb0-8ed9-5e5f24396021$SATQ$::uuid, $SATQ$207f4f99-66dd-4d15-9c4f-d66ec6fb37b3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The popular wood-wide web theory posits that trees can communicate and exchange resources with one another via common mycorrhizal networks (CMNs) of fungi.</li>
<li>Ecologist Dr. Suzanne Simard first suggested this theory in 1997.</li>
<li>She described trees as &ldquo;super-cooperators.&rdquo;</li>
<li>In the 2022 study &ldquo;The Decay of the Wood-Wide Web?,&rdquo; mycologist Dr. Justine Karst and colleagues evaluated dozens of CMN studies.</li>
<li>They write that CMNs &ldquo;have captured the interest of broad audiences. We are concerned, however, that recent claims about CMNs in forests are disconnected from evidence.&rdquo;</li>
</ul>$SATQ$, $SATQ$<p>The student wants to use a quotation to emphasize a potential problem with the wood-wide web theory. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"e5b5f94d-e018-4aea-9a37-4238308d80fc","content":"<p>Describing trees as &ldquo;super-cooperators,&rdquo; Simard first suggested that trees can exchange resources with one another in 1997.</p>"},{"id":"6f92137c-2323-4abb-9dd3-c68215853d67","content":"<p>In &ldquo;The Decay of the Wood-Wide Web?,&rdquo; Karst and colleagues note that common mycorrhizal networks &ldquo;have captured the interest of broad audiences.&rdquo;</p>"},{"id":"df3b0bad-86c5-4db8-ba7e-ba44563daa44","content":"<p>After evaluating dozens of CMN studies, Karst and colleagues expressed concern that recent claims about common mycorrhizal networks are &ldquo;disconnected from evidence.&rdquo;</p>"},{"id":"e9abfc47-a30e-42c0-bed5-fd6cfb16d3b3","content":"<p>Despite the concerns expressed in the 2022 study &ldquo;The Decay of the Wood-Wide Web?,&rdquo; the wood-wide web theory remains popular.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["df3b0bad-86c5-4db8-ba7e-ba44563daa44"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. This choice uses a quotation to convey the authors&rsquo; criticism and challenge to the wood-wide web theory due to an absence of evidence. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize a potential problem with the wood-wide web theory. It uses a quotation to introduce the theory and its originator. It doesn&rsquo;t mention any criticism or challenge to the theory. Choice B is incorrect. This choice uses a quotation, but it doesn&rsquo;t emphasize a potential problem with the wood-wide web theory. It uses a quotation to describe the appeal and interest of the theory, but it doesn&rsquo;t indicate why the authors are concerned or what evidence they have. Choice D is incorrect. This choice doesn&rsquo;t use a quotation at all. It paraphrases the main idea of the 2022 study, but it doesn&rsquo;t include any specific words or phrases from the notes. It also doesn&rsquo;t emphasize a potential problem with the theory, but rather its popularity. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-H010$SATQ$, $SATQ$$SATQ$, $SATQ$58b3d979-ac2c-4508-9024-ec079fb85f59$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"fdd9a360","external_id":"e1a88e15-d0ab-4fb0-8ed9-5e5f24396021","vaultid":"207f4f99-66dd-4d15-9c4f-d66ec6fb37b3","uId":"743363a7-47a6-4050-9867-8ab3f48c60f2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The popular wood-wide web theory posits that trees can communicate and exchange resources with one another via common mycorrhizal networks (CMNs) of fungi.</li>\n<li>Ecologist Dr. Suzanne Simard first suggested this theory in 1997.</li>\n<li>She described trees as &ldquo;super-cooperators.&rdquo;</li>\n<li>In the 2022 study &ldquo;The Decay of the Wood-Wide Web?,&rdquo; mycologist Dr. Justine Karst and colleagues evaluated dozens of CMN studies.</li>\n<li>They write that CMNs &ldquo;have captured the interest of broad audiences. We are concerned, however, that recent claims about CMNs in forests are disconnected from evidence.&rdquo;</li>\n</ul>","stem":"<p>The student wants to use a quotation to emphasize a potential problem with the wood-wide web theory. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"e5b5f94d-e018-4aea-9a37-4238308d80fc","content":"<p>Describing trees as &ldquo;super-cooperators,&rdquo; Simard first suggested that trees can exchange resources with one another in 1997.</p>"},{"id":"6f92137c-2323-4abb-9dd3-c68215853d67","content":"<p>In &ldquo;The Decay of the Wood-Wide Web?,&rdquo; Karst and colleagues note that common mycorrhizal networks &ldquo;have captured the interest of broad audiences.&rdquo;</p>"},{"id":"df3b0bad-86c5-4db8-ba7e-ba44563daa44","content":"<p>After evaluating dozens of CMN studies, Karst and colleagues expressed concern that recent claims about common mycorrhizal networks are &ldquo;disconnected from evidence.&rdquo;</p>"},{"id":"e9abfc47-a30e-42c0-bed5-fd6cfb16d3b3","content":"<p>Despite the concerns expressed in the 2022 study &ldquo;The Decay of the Wood-Wide Web?,&rdquo; the wood-wide web theory remains popular.</p>"}],"keys":["df3b0bad-86c5-4db8-ba7e-ba44563daa44"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. This choice uses a quotation to convey the authors&rsquo; criticism and challenge to the wood-wide web theory due to an absence of evidence. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize a potential problem with the wood-wide web theory. It uses a quotation to introduce the theory and its originator. It doesn&rsquo;t mention any criticism or challenge to the theory. Choice B is incorrect. This choice uses a quotation, but it doesn&rsquo;t emphasize a potential problem with the wood-wide web theory. It uses a quotation to describe the appeal and interest of the theory, but it doesn&rsquo;t indicate why the authors are concerned or what evidence they have. Choice D is incorrect. This choice doesn&rsquo;t use a quotation at all. It paraphrases the main idea of the 2022 study, but it doesn&rsquo;t include any specific words or phrases from the notes. It also doesn&rsquo;t emphasize a potential problem with the theory, but rather its popularity. </p>","parenttemplatename":"OSP-KA-SYN-H010","parenttemplateid":"","templateclusterid":"58b3d979-ac2c-4508-9024-ec079fb85f59","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$feb1e6da$SATQ$, $SATQ$c8957ff2-9674-47a3-a4d1-718331694c42$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Biographer Michael Gorra notes that the novelist Henry James &ldquo;lived in a world of second thoughts,&rdquo; frequently tinkering with his novels and stories after their initial publication. However, the differences between the 1881 first edition and the 1908 edition of his novel <em>A Portrait of a Lady</em> are extreme, even by James&rsquo;s standards; <span aria-hidden="true">______</span><span class="sr-only">blank</span> some critics regard the two editions as two different novels altogether.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"1272fe13-9b2c-43e0-a86d-ebd0e9acdbdb","content":"<p>by contrast,</p>"},{"id":"bfc53f51-fc2c-44cf-8858-76a9b3a69e1b","content":"<p>in fact,&nbsp;</p>"},{"id":"94517322-f806-4795-8218-392b0cc940e2","content":"<p>nevertheless,</p>"},{"id":"cce5018a-8a9e-417f-a157-7c2a2e8212e7","content":"<p>in other words,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["bfc53f51-fc2c-44cf-8858-76a9b3a69e1b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "In fact" logically signals that the critics&rsquo; claim at the end of this sentence&mdash;that the two editions are essentially two different novels altogether&mdash;offers additional emphasis in support of the previous claim that the differences between the editions are extreme.</p><p>Choice A is incorrect because "by contrast" illogically signals that the claim at the end of this sentence contrasts with the previous claim about the differences between the editions. Instead, the critics&rsquo; opinion offers additional emphasis in support of that claim. Choice C is incorrect because "nevertheless" illogically signals that the claim at the end of this sentence is true despite the previous claim about the differences between the two editions. Instead, the critics&rsquo; opinion offers additional emphasis in support of that claim. Choice D is incorrect because "in other words" illogically signals that the claim at the end of this sentence is merely paraphrasing the previous claim about the differences between the two editions. The critics&rsquo; opinion adds new information to the previous claim rather than simply paraphrasing it.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"feb1e6da","external_id":"c8957ff2-9674-47a3-a4d1-718331694c42","vaultid":null,"uId":"7a6a6d7a-41be-4a24-ba74-0ee0b2d7edd6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Biographer Michael Gorra notes that the novelist Henry James &ldquo;lived in a world of second thoughts,&rdquo; frequently tinkering with his novels and stories after their initial publication. However, the differences between the 1881 first edition and the 1908 edition of his novel <em>A Portrait of a Lady</em> are extreme, even by James&rsquo;s standards; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> some critics regard the two editions as two different novels altogether.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"1272fe13-9b2c-43e0-a86d-ebd0e9acdbdb","content":"<p>by contrast,</p>"},{"id":"bfc53f51-fc2c-44cf-8858-76a9b3a69e1b","content":"<p>in fact,&nbsp;</p>"},{"id":"94517322-f806-4795-8218-392b0cc940e2","content":"<p>nevertheless,</p>"},{"id":"cce5018a-8a9e-417f-a157-7c2a2e8212e7","content":"<p>in other words,</p>"}],"keys":["bfc53f51-fc2c-44cf-8858-76a9b3a69e1b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"In fact\" logically signals that the critics&rsquo; claim at the end of this sentence&mdash;that the two editions are essentially two different novels altogether&mdash;offers additional emphasis in support of the previous claim that the differences between the editions are extreme.</p><p>Choice A is incorrect because \"by contrast\" illogically signals that the claim at the end of this sentence contrasts with the previous claim about the differences between the editions. Instead, the critics&rsquo; opinion offers additional emphasis in support of that claim. Choice C is incorrect because \"nevertheless\" illogically signals that the claim at the end of this sentence is true despite the previous claim about the differences between the two editions. Instead, the critics&rsquo; opinion offers additional emphasis in support of that claim. Choice D is incorrect because \"in other words\" illogically signals that the claim at the end of this sentence is merely paraphrasing the previous claim about the differences between the two editions. The critics&rsquo; opinion adds new information to the previous claim rather than simply paraphrasing it.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323043,"updateDate":1730147323043}$SATQ$::jsonb, 1730147323043, 1730147323043),
    ($SATQ$ff1a2e5e$SATQ$, $SATQ$2ff3132b-4962-463f-892c-bc76a6db68bf$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Historians agree that the jazz pianist Jelly Roll Morton was exaggerating when he claimed to have invented jazz music. No one can deny, <span aria-hidden="true">______</span><span class="sr-only">blank</span> that Morton&rsquo;s innovative compositions and remarkable improvisational skills helped shape jazz as a genre during its early years.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"cde15df7-1fd4-4ed4-bbd2-6fae7bb54c5e","content":"<p>therefore,</p>"},{"id":"3cc2e273-6e08-4fbb-b687-717f348d0985","content":"<p>in the second place,</p>"},{"id":"638d7f80-ae6b-4f36-aa34-eceb39227986","content":"<p>in other words,</p>"},{"id":"39dc81c2-bf1e-4282-a1e1-45bcf769cc2f","content":"<p>though,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["39dc81c2-bf1e-4282-a1e1-45bcf769cc2f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Though" logically signals that the claim in the sentence&mdash;that Morton&rsquo;s improvisational skills helped shape jazz as a genre during its early years ("No one can deny" it)&mdash;is true despite the previous information about Morton&rsquo;s exaggerated claim to have invented jazz.</p><p>Choice A is incorrect because "therefore" illogically signals that the claim in the sentence is a result of the previous information about Morton&rsquo;s claim to have invented jazz. Instead, the sentence states that Morton helped to shape jazz&mdash;even if his claim was an exaggeration. Choice B is incorrect because "in the second place" illogically signals that the claim in the sentence is a second, separate point in addition to Morton&rsquo;s claim to have invented jazz. Instead, the sentence states that Morton helped to shape jazz&mdash;even if his claim was an exaggeration. Choice C is incorrect because "in other words" illogically signals that the claim in the sentence is merely a paraphrase or restatement of the previous information about Morton&rsquo;s claim to have invented jazz. Instead, the sentence states that Morton helped to shape jazz&mdash;even if his claim was an exaggeration.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ff1a2e5e","external_id":"2ff3132b-4962-463f-892c-bc76a6db68bf","vaultid":null,"uId":"c299608c-df7e-4072-9ac7-c8052145941a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Historians agree that the jazz pianist Jelly Roll Morton was exaggerating when he claimed to have invented jazz music. No one can deny, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> that Morton&rsquo;s innovative compositions and remarkable improvisational skills helped shape jazz as a genre during its early years.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"cde15df7-1fd4-4ed4-bbd2-6fae7bb54c5e","content":"<p>therefore,</p>"},{"id":"3cc2e273-6e08-4fbb-b687-717f348d0985","content":"<p>in the second place,</p>"},{"id":"638d7f80-ae6b-4f36-aa34-eceb39227986","content":"<p>in other words,</p>"},{"id":"39dc81c2-bf1e-4282-a1e1-45bcf769cc2f","content":"<p>though,</p>"}],"keys":["39dc81c2-bf1e-4282-a1e1-45bcf769cc2f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Though\" logically signals that the claim in the sentence&mdash;that Morton&rsquo;s improvisational skills helped shape jazz as a genre during its early years (\"No one can deny\" it)&mdash;is true despite the previous information about Morton&rsquo;s exaggerated claim to have invented jazz.</p><p>Choice A is incorrect because \"therefore\" illogically signals that the claim in the sentence is a result of the previous information about Morton&rsquo;s claim to have invented jazz. Instead, the sentence states that Morton helped to shape jazz&mdash;even if his claim was an exaggeration. Choice B is incorrect because \"in the second place\" illogically signals that the claim in the sentence is a second, separate point in addition to Morton&rsquo;s claim to have invented jazz. Instead, the sentence states that Morton helped to shape jazz&mdash;even if his claim was an exaggeration. Choice C is incorrect because \"in other words\" illogically signals that the claim in the sentence is merely a paraphrase or restatement of the previous information about Morton&rsquo;s claim to have invented jazz. Instead, the sentence states that Morton helped to shape jazz&mdash;even if his claim was an exaggeration.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$ff3865b3$SATQ$, $SATQ$75e7d111-ced9-4da0-9be1-0c9cd8da1f3b$SATQ$::uuid, $SATQ$8588c0ed-3c0d-4f4a-8008-ffce632ccbe4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>A wok is a cooking pan that originated in China during the Han dynasty (206 BCE&ndash;220 CE).</li>
<li>The wok&rsquo;s round, wide base helps to cook food evenly.</li>
<li>The wok&rsquo;s high, angled sides help to contain oil splatters.</li>
<li>Grace Young is a cook and culinary historian.</li>
<li>Her book <em>The Breath of a Wok</em> (2004) traces the history of the wok.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to describe the wok&rsquo;s shape. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"80c51116-a2f0-4874-972d-797fa82a3fd5","content":"<p>Grace Young&rsquo;s 2004 book, <em>The Breath of a Wok</em>, traces the history of the cooking pan.</p>"},{"id":"4c078e9f-abc1-456b-95b6-309354647fbf","content":"<p>Able to cook food evenly and contain oil splatters, the wok is the subject of Grace Young&rsquo;s 2004 book.</p>"},{"id":"2c2c5a6a-f799-46b4-be4d-b1770c63ada0","content":"<p>A wok is a cooking pan with a round, wide base and high, angled sides.</p>"},{"id":"124239e5-256d-4e96-bfda-c1e91a7e3962","content":"<p>The design of a wok, a type of cooking pan that originated in China during the Han dynasty, helps the pan cook food evenly and contain oil splatters.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["2c2c5a6a-f799-46b4-be4d-b1770c63ada0"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. It summarizes the information that describes the wok&rsquo;s shape from the second and third bullet points. </p><p>Choice A is incorrect. This choice doesn&rsquo;t describe the shape of a wok. Choice B is incorrect. This choice doesn&rsquo;t describe the shape of a wok, just some of its features. Choice D is incorrect. This choice doesn&rsquo;t describe the shape of a wok, only some of its benefits or functions. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-M001$SATQ$, $SATQ$$SATQ$, $SATQ$ef690ce5-08f7-493d-bda8-81bd5ff52ad3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ff3865b3","external_id":"75e7d111-ced9-4da0-9be1-0c9cd8da1f3b","vaultid":"8588c0ed-3c0d-4f4a-8008-ffce632ccbe4","uId":"71f9670f-083c-4d43-b80e-42beac74c241","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>A wok is a cooking pan that originated in China during the Han dynasty (206 BCE&ndash;220 CE).</li>\n<li>The wok&rsquo;s round, wide base helps to cook food evenly.</li>\n<li>The wok&rsquo;s high, angled sides help to contain oil splatters.</li>\n<li>Grace Young is a cook and culinary historian.</li>\n<li>Her book <em>The Breath of a Wok</em> (2004) traces the history of the wok.</li>\n</ul>","stem":"<p>The student wants to describe the wok&rsquo;s shape. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"80c51116-a2f0-4874-972d-797fa82a3fd5","content":"<p>Grace Young&rsquo;s 2004 book, <em>The Breath of a Wok</em>, traces the history of the cooking pan.</p>"},{"id":"4c078e9f-abc1-456b-95b6-309354647fbf","content":"<p>Able to cook food evenly and contain oil splatters, the wok is the subject of Grace Young&rsquo;s 2004 book.</p>"},{"id":"2c2c5a6a-f799-46b4-be4d-b1770c63ada0","content":"<p>A wok is a cooking pan with a round, wide base and high, angled sides.</p>"},{"id":"124239e5-256d-4e96-bfda-c1e91a7e3962","content":"<p>The design of a wok, a type of cooking pan that originated in China during the Han dynasty, helps the pan cook food evenly and contain oil splatters.</p>"}],"keys":["2c2c5a6a-f799-46b4-be4d-b1770c63ada0"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. It summarizes the information that describes the wok&rsquo;s shape from the second and third bullet points. </p><p>Choice A is incorrect. This choice doesn&rsquo;t describe the shape of a wok. Choice B is incorrect. This choice doesn&rsquo;t describe the shape of a wok, just some of its features. Choice D is incorrect. This choice doesn&rsquo;t describe the shape of a wok, only some of its benefits or functions. </p>","parenttemplatename":"OSP-KA-SYN-M001","parenttemplateid":"","templateclusterid":"ef690ce5-08f7-493d-bda8-81bd5ff52ad3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$ff8d2125$SATQ$, $SATQ$31f36559-8bb0-4c98-b21a-c714433d07f2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Crown shyness is a phenomenon in which the tops (crowns) of neighboring trees grow close together but don&rsquo;t overlap.</li>
<li>To explain how this happens, Australian forester M.R. Jacobs proposes the mutual abrasion theory.</li>
<li>According to Jacobs&rsquo;s theory, when trees brush against one another, branches break off.</li>
<li>Malaysian scholar Francis S.P. Ng posits the mutual shade avoidance theory.</li>
<li>According to Ng&rsquo;s theory, when tree branches detect shade from nearby trees&rsquo; branches, they stop growing.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to compare the causes of crown shyness proposed in the two theories. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"14578cbf-073b-49bd-a48f-92ed0e51ed43","content":"<p>While Jacobs proposes that crown shyness is caused by neighboring tree branches brushing against one another, Ng posits that it occurs when branches detect shade from nearby trees&rsquo; branches.</p>"},{"id":"ad4efcc5-50f3-4f46-985c-dd28df16fcb9","content":"<p>Both Jacobs and Ng have proposed theories to explain what causes crown shyness.</p>"},{"id":"9f39ccc5-a914-4075-be8c-0f085e80df71","content":"<p>Ng posits the mutual shade avoidance theory, whereas Jacobs proposes an alternative theory.</p>"},{"id":"f9db32a7-a4ea-4331-b39e-944bd162e876","content":"<p>Jacobs&rsquo;s mutual abrasion theory proposes that when neighboring trees brush against one another, branches break off, resulting in a phenomenon in which the tops of trees grow close together but don&rsquo;t overlap.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["14578cbf-073b-49bd-a48f-92ed0e51ed43"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence compares the two proposed causes of crown shyness, noting the theories&rsquo; differences: Jacobs cites branches brushing against one another as the cause, while Ng cites branches detecting shade from other branches as the cause.</p><p>Choice B is incorrect. The sentence merely identifies the existence of two theories for crown shyness; it doesn&rsquo;t compare the causes proposed by each theory. Choice C is incorrect. The sentence merely indicates that there are two different theories for crown shyness; it doesn&rsquo;t compare the causes proposed by each theory. Choice D is incorrect. The sentence merely explains one theory for crown shyness; it doesn&rsquo;t compare two theories.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ff8d2125","external_id":"31f36559-8bb0-4c98-b21a-c714433d07f2","vaultid":null,"uId":"3c05c64c-f672-4390-b7ec-6b8d0a1586fe","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Crown shyness is a phenomenon in which the tops (crowns) of neighboring trees grow close together but don&rsquo;t overlap.</li>\n<li>To explain how this happens, Australian forester M.R. Jacobs proposes the mutual abrasion theory.</li>\n<li>According to Jacobs&rsquo;s theory, when trees brush against one another, branches break off.</li>\n<li>Malaysian scholar Francis S.P. Ng posits the mutual shade avoidance theory.</li>\n<li>According to Ng&rsquo;s theory, when tree branches detect shade from nearby trees&rsquo; branches, they stop growing.</li>\n</ul>","stem":"<p>The student wants to compare the causes of crown shyness proposed in the two theories. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"14578cbf-073b-49bd-a48f-92ed0e51ed43","content":"<p>While Jacobs proposes that crown shyness is caused by neighboring tree branches brushing against one another, Ng posits that it occurs when branches detect shade from nearby trees&rsquo; branches.</p>"},{"id":"ad4efcc5-50f3-4f46-985c-dd28df16fcb9","content":"<p>Both Jacobs and Ng have proposed theories to explain what causes crown shyness.</p>"},{"id":"9f39ccc5-a914-4075-be8c-0f085e80df71","content":"<p>Ng posits the mutual shade avoidance theory, whereas Jacobs proposes an alternative theory.</p>"},{"id":"f9db32a7-a4ea-4331-b39e-944bd162e876","content":"<p>Jacobs&rsquo;s mutual abrasion theory proposes that when neighboring trees brush against one another, branches break off, resulting in a phenomenon in which the tops of trees grow close together but don&rsquo;t overlap.</p>"}],"keys":["14578cbf-073b-49bd-a48f-92ed0e51ed43"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence compares the two proposed causes of crown shyness, noting the theories&rsquo; differences: Jacobs cites branches brushing against one another as the cause, while Ng cites branches detecting shade from other branches as the cause.</p><p>Choice B is incorrect. The sentence merely identifies the existence of two theories for crown shyness; it doesn&rsquo;t compare the causes proposed by each theory. Choice C is incorrect. The sentence merely indicates that there are two different theories for crown shyness; it doesn&rsquo;t compare the causes proposed by each theory. Choice D is incorrect. The sentence merely explains one theory for crown shyness; it doesn&rsquo;t compare two theories.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323031,"updateDate":1730147323031}$SATQ$::jsonb, 1730147323031, 1730147323031),
    ($SATQ$003f22c8$SATQ$, $SATQ$a61d8163-0a69-4a71-a077-552447476d6e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Every last second of space shuttle mission STS-79, which lasted ten days and three hours, <span aria-hidden="true">______</span><span class="sr-only">blank</span> carefully monitored by a team of experts.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7d5b2c76-7738-4a3f-860d-cb48d98edf0c","content":"<p>have been</p>"},{"id":"53e39787-215b-4165-89b6-4c3d5ad2354d","content":"<p>are</p>"},{"id":"f8cbf571-486b-41bc-a194-c79074b5d893","content":"<p>was</p>"},{"id":"a6087a49-a4e4-406c-ac7b-71193da28663","content":"<p>were</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f8cbf571-486b-41bc-a194-c79074b5d893"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb "was" agrees in number with the singular subject "every last second."</p><p>Choice A is incorrect because the plural verb "have been" doesn&rsquo;t agree in number with the singular subject "every last second." Choice B is incorrect because the plural verb "are" doesn&rsquo;t agree in number with the singular subject "every last second." Choice D is incorrect because the plural verb "were" doesn&rsquo;t agree in number with the singular subject "every last second."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"003f22c8","external_id":"a61d8163-0a69-4a71-a077-552447476d6e","vaultid":null,"uId":"4aea8fc1-0748-415c-80f5-4e8b5d7dca31","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Every last second of space shuttle mission STS-79, which lasted ten days and three hours, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> carefully monitored by a team of experts.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7d5b2c76-7738-4a3f-860d-cb48d98edf0c","content":"<p>have been</p>"},{"id":"53e39787-215b-4165-89b6-4c3d5ad2354d","content":"<p>are</p>"},{"id":"f8cbf571-486b-41bc-a194-c79074b5d893","content":"<p>was</p>"},{"id":"a6087a49-a4e4-406c-ac7b-71193da28663","content":"<p>were</p>"}],"keys":["f8cbf571-486b-41bc-a194-c79074b5d893"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb \"was\" agrees in number with the singular subject \"every last second.\"</p><p>Choice A is incorrect because the plural verb \"have been\" doesn&rsquo;t agree in number with the singular subject \"every last second.\" Choice B is incorrect because the plural verb \"are\" doesn&rsquo;t agree in number with the singular subject \"every last second.\" Choice D is incorrect because the plural verb \"were\" doesn&rsquo;t agree in number with the singular subject \"every last second.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$01a32c84$SATQ$, $SATQ$60e94864-ffe8-48d1-bb47-dcb67d33a020$SATQ$::uuid, $SATQ$eb9cdc0f-0a81-4e17-9340-a7c6cde8f6e1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The first computerized spreadsheet, Dan Bricklin&rsquo;s <em>VisiCalc</em>, improved financial recordkeeping not only by providing users with an easy means of adjusting data in spreadsheets but also by automatically updating all calculations that were dependent on these <span aria-hidden="true">______</span><span class="sr-only">blank</span> to VisiCalc&rsquo;s release, changing a paper spreadsheet often required redoing the entire sheet by hand, a process that could take days.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"024246ed-6742-428c-bf62-40a2c21ab8d9","content":"<p>adjustments prior</p>"},{"id":"86476f3a-8385-4bcf-874c-39238635e7e3","content":"<p>adjustments, prior&nbsp;</p>"},{"id":"ffe2af69-6d54-4129-8012-e1000705e0c7","content":"<p>adjustments. Prior</p>"},{"id":"b8bf18ce-8b59-4eda-9e81-22340bbedb53","content":"<p>adjustments and prior</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ffe2af69-6d54-4129-8012-e1000705e0c7"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between the first sentence (&ldquo;The...adjustments&rdquo;) and the second sentence (&ldquo;Prior...days&rdquo;). Because the adverbial phrase beginning with &ldquo;prior&rdquo; indicates when changing a spreadsheet required redoing the sheet by hand, that phrase belongs with the second sentence.&nbsp;</p><p>Choice A is incorrect because it results in a run-on sentence. Two sentences are fused without punctuation and/or a conjunction. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join the sentences. </p>$SATQ$, false, 0, $SATQ$OSP-696-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$7d55841e-98f8-4c2f-841c-e995112c1668$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"01a32c84","external_id":"60e94864-ffe8-48d1-bb47-dcb67d33a020","vaultid":"eb9cdc0f-0a81-4e17-9340-a7c6cde8f6e1","uId":"6ba8b963-3f09-414a-9c88-75321de65f6f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The first computerized spreadsheet, Dan Bricklin&rsquo;s <em>VisiCalc</em>, improved financial recordkeeping not only by providing users with an easy means of adjusting data in spreadsheets but also by automatically updating all calculations that were dependent on these <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> to VisiCalc&rsquo;s release, changing a paper spreadsheet often required redoing the entire sheet by hand, a process that could take days.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"024246ed-6742-428c-bf62-40a2c21ab8d9","content":"<p>adjustments prior</p>"},{"id":"86476f3a-8385-4bcf-874c-39238635e7e3","content":"<p>adjustments, prior&nbsp;</p>"},{"id":"ffe2af69-6d54-4129-8012-e1000705e0c7","content":"<p>adjustments. Prior</p>"},{"id":"b8bf18ce-8b59-4eda-9e81-22340bbedb53","content":"<p>adjustments and prior</p>"}],"keys":["ffe2af69-6d54-4129-8012-e1000705e0c7"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between the first sentence (&ldquo;The...adjustments&rdquo;) and the second sentence (&ldquo;Prior...days&rdquo;). Because the adverbial phrase beginning with &ldquo;prior&rdquo; indicates when changing a spreadsheet required redoing the sheet by hand, that phrase belongs with the second sentence.&nbsp;</p><p>Choice A is incorrect because it results in a run-on sentence. Two sentences are fused without punctuation and/or a conjunction. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join the sentences. </p>","parenttemplatename":"OSP-696-SEC","parenttemplateid":"","templateclusterid":"7d55841e-98f8-4c2f-841c-e995112c1668","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$02871a0d$SATQ$, $SATQ$b3b3570a-d5e7-47c2-a583-aee897edbc4f$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In her large-scale sculpture<em> Casa-Isla</em>, artist Edra Soto included references to her childhood in Puerto Rico. For example, the sculpture&rsquo;s steel panels have a crisscrossing pattern inspired by the iron gates <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"058fcd58-e196-41e5-a994-a0f15c1d7eb6","content":"<p>Soto would see in her neighborhood?</p>"},{"id":"d0dc33de-71f3-4d9b-9017-9c665d9b696f","content":"<p>Soto would see in her neighborhood.</p>"},{"id":"029c1b53-c161-4cf7-9adc-e3a4d6f4438e","content":"<p>would Soto see in her neighborhood.</p>"},{"id":"c616ab09-9db0-4ebf-af9b-34394f399524","content":"<p>would Soto see in her neighborhood?</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["d0dc33de-71f3-4d9b-9017-9c665d9b696f"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a period to punctuate a declarative sentence ("For example...neighborhood").</p><p>Choice A is incorrect. It&rsquo;s unconventional to use a question mark in this way to punctuate a declarative sentence. Choice C is incorrect. The structure requires a declarative clause at the end of the sentence that states where Soto saw the steel panels, not an incomplete interrogative clause that asks a direct question, such as "would Soto see in her neighborhood." Choice D is incorrect. The structure requires a period and a declarative clause at the end of the sentence that states where Soto saw the steel panels, not an incomplete interrogative clause asking a direct question, such as "would Soto see in her neighborhood?"</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"02871a0d","external_id":"b3b3570a-d5e7-47c2-a583-aee897edbc4f","vaultid":null,"uId":"a80d9fed-6e85-4c80-ad81-819b0360486f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In her large-scale sculpture<em> Casa-Isla</em>, artist Edra Soto included references to her childhood in Puerto Rico. For example, the sculpture&rsquo;s steel panels have a crisscrossing pattern inspired by the iron gates <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"058fcd58-e196-41e5-a994-a0f15c1d7eb6","content":"<p>Soto would see in her neighborhood?</p>"},{"id":"d0dc33de-71f3-4d9b-9017-9c665d9b696f","content":"<p>Soto would see in her neighborhood.</p>"},{"id":"029c1b53-c161-4cf7-9adc-e3a4d6f4438e","content":"<p>would Soto see in her neighborhood.</p>"},{"id":"c616ab09-9db0-4ebf-af9b-34394f399524","content":"<p>would Soto see in her neighborhood?</p>"}],"keys":["d0dc33de-71f3-4d9b-9017-9c665d9b696f"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a period to punctuate a declarative sentence (\"For example...neighborhood\").</p><p>Choice A is incorrect. It&rsquo;s unconventional to use a question mark in this way to punctuate a declarative sentence. Choice C is incorrect. The structure requires a declarative clause at the end of the sentence that states where Soto saw the steel panels, not an incomplete interrogative clause that asks a direct question, such as \"would Soto see in her neighborhood.\" Choice D is incorrect. The structure requires a period and a declarative clause at the end of the sentence that states where Soto saw the steel panels, not an incomplete interrogative clause asking a direct question, such as \"would Soto see in her neighborhood?\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323049,"updateDate":1730147323049}$SATQ$::jsonb, 1730147323049, 1730147323049),
    ($SATQ$028752cd$SATQ$, $SATQ$f096c551-d21f-4560-8fdf-891ce0647d0e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The Dust Bowl was a period of severe drought that plagued the Great Plains of the US during the 1930s. During this time, dust storms <span aria-hidden="true">______</span><span class="sr-only">blank</span> over 100 million acres of land. They even reached as far east as New York City.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"aebbdbab-a847-40ea-92a9-98dc901c819f","content":"<p>are affecting</p>"},{"id":"0d11c72f-310a-4cb2-b349-af0cb6b0acd5","content":"<p>will have affected</p>"},{"id":"28b90907-3987-4761-901f-cdd097d8a9eb","content":"<p>will affect</p>"},{"id":"16ba93ce-4193-4405-a4e8-ccc538c2a59f","content":"<p>affected</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["16ba93ce-4193-4405-a4e8-ccc538c2a59f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb "affected," used in conjunction with the phrase "during this time," correctly indicates that the dust storms occurred in the 1930s.</p><p>Choice A is incorrect because the present progressive tense verb "are affecting" doesn&rsquo;t indicate that the dust storms occurred in the 1930s. Choice B is incorrect because the future perfect tense verb "will have affected" doesn&rsquo;t indicate that the dust storms occurred in the 1930s. Choice C is incorrect because the future tense verb "will affect" doesn&rsquo;t indicate that the dust storms occurred in the 1930s.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"028752cd","external_id":"f096c551-d21f-4560-8fdf-891ce0647d0e","vaultid":null,"uId":"ced225b7-eae4-4571-8aed-15e3fce65340","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The Dust Bowl was a period of severe drought that plagued the Great Plains of the US during the 1930s. During this time, dust storms <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> over 100 million acres of land. They even reached as far east as New York City.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"aebbdbab-a847-40ea-92a9-98dc901c819f","content":"<p>are affecting</p>"},{"id":"0d11c72f-310a-4cb2-b349-af0cb6b0acd5","content":"<p>will have affected</p>"},{"id":"28b90907-3987-4761-901f-cdd097d8a9eb","content":"<p>will affect</p>"},{"id":"16ba93ce-4193-4405-a4e8-ccc538c2a59f","content":"<p>affected</p>"}],"keys":["16ba93ce-4193-4405-a4e8-ccc538c2a59f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb \"affected,\" used in conjunction with the phrase \"during this time,\" correctly indicates that the dust storms occurred in the 1930s.</p><p>Choice A is incorrect because the present progressive tense verb \"are affecting\" doesn&rsquo;t indicate that the dust storms occurred in the 1930s. Choice B is incorrect because the future perfect tense verb \"will have affected\" doesn&rsquo;t indicate that the dust storms occurred in the 1930s. Choice C is incorrect because the future tense verb \"will affect\" doesn&rsquo;t indicate that the dust storms occurred in the 1930s.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669215,"updateDate":1743430669215}$SATQ$::jsonb, 1743430669215, 1743430669215),
    ($SATQ$02913383$SATQ$, $SATQ$378a8677-6d3d-414b-a804-6497ccf8c231$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;He was just the man for such a place, and it was just the place for such a man.&rdquo; This line is from Frederick Douglass&rsquo;s autobiography <em>Narrative of the Life of Frederick Douglass</em> (1845). It&rsquo;s an example of antimetabole, a writing technique that <span aria-hidden="true">______</span><span class="sr-only">blank</span> emphasis by repeating a statement in a reversed order.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"51b83d52-55a3-47fe-9baf-8e1d3daae42f","content":"<p>create</p>"},{"id":"0751eb5d-4ac8-4bd6-8fcc-35ce92b43633","content":"<p>are creating</p>"},{"id":"ec68c16a-71b5-47ba-90ab-44c7c8086c30","content":"<p>have created</p>"},{"id":"308b987c-014f-441b-ae92-e53d94f9ab63","content":"<p>creates</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["308b987c-014f-441b-ae92-e53d94f9ab63"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb "creates" agrees in number with the singular subject "technique."</p><p>Choice A is incorrect because the plural verb "create" doesn&rsquo;t agree in number with the singular subject "technique." Choice B is incorrect because the plural verb "are creating" doesn&rsquo;t agree in number with the singular subject "technique." Choice C is incorrect because the plural verb "have created" doesn&rsquo;t agree in number with the singular subject "technique."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"02913383","external_id":"378a8677-6d3d-414b-a804-6497ccf8c231","vaultid":null,"uId":"db16eedf-b661-41f2-b63d-637bddad6810","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>&ldquo;He was just the man for such a place, and it was just the place for such a man.&rdquo; This line is from Frederick Douglass&rsquo;s autobiography <em>Narrative of the Life of Frederick Douglass</em> (1845). It&rsquo;s an example of antimetabole, a writing technique that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> emphasis by repeating a statement in a reversed order.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"51b83d52-55a3-47fe-9baf-8e1d3daae42f","content":"<p>create</p>"},{"id":"0751eb5d-4ac8-4bd6-8fcc-35ce92b43633","content":"<p>are creating</p>"},{"id":"ec68c16a-71b5-47ba-90ab-44c7c8086c30","content":"<p>have created</p>"},{"id":"308b987c-014f-441b-ae92-e53d94f9ab63","content":"<p>creates</p>"}],"keys":["308b987c-014f-441b-ae92-e53d94f9ab63"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb \"creates\" agrees in number with the singular subject \"technique.\"</p><p>Choice A is incorrect because the plural verb \"create\" doesn&rsquo;t agree in number with the singular subject \"technique.\" Choice B is incorrect because the plural verb \"are creating\" doesn&rsquo;t agree in number with the singular subject \"technique.\" Choice C is incorrect because the plural verb \"have created\" doesn&rsquo;t agree in number with the singular subject \"technique.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$035fd57e$SATQ$, $SATQ$18df74c1-ac99-42bf-bb82-f63d79a72cb9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The rough frog is a species of amphibian native to Australia. Currently, the frog&rsquo;s range <span aria-hidden="true">______</span><span class="sr-only">blank</span> parts of northern New South Wales and southeastern Queensland.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"be974064-9eda-4879-be80-06b21f19e9f2","content":"<p>includes</p>"},{"id":"191e8153-30ae-4242-be2c-5daf5603cdce","content":"<p>included</p>"},{"id":"84518f3c-2cbd-4614-adb6-d92eac707634","content":"<p>will have included</p>"},{"id":"aa41d083-b99c-4114-bcc4-528c76a1046a","content":"<p>had included</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["be974064-9eda-4879-be80-06b21f19e9f2"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb &ldquo;includes,&rdquo; used in conjunction with the word &ldquo;currently,&rdquo; correctly indicates that the frog&rsquo;s current range includes parts of northern New South Wales and southeastern Queensland.</p><p>Choice B is incorrect because the past tense verb &ldquo;included&rdquo; doesn&rsquo;t indicate that the frog&rsquo;s range currently includes parts of northern New South Wales and southeastern Queensland. Choice C is incorrect because the future perfect tense &ldquo;will have included&rdquo; doesn&rsquo;t indicate that the frog&rsquo;s range currently includes parts of northern New South Wales and southeastern Queensland. Choice D is incorrect because the past perfect tense &ldquo;had included&rdquo; doesn&rsquo;t indicate that the frog&rsquo;s range currently includes parts of northern New South Wales and southeastern Queensland.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"035fd57e","external_id":"18df74c1-ac99-42bf-bb82-f63d79a72cb9","vaultid":null,"uId":"1346d718-e6a6-48d8-bfa5-1d7e8213a6a8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The rough frog is a species of amphibian native to Australia. Currently, the frog&rsquo;s range <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> parts of northern New South Wales and southeastern Queensland.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"be974064-9eda-4879-be80-06b21f19e9f2","content":"<p>includes</p>"},{"id":"191e8153-30ae-4242-be2c-5daf5603cdce","content":"<p>included</p>"},{"id":"84518f3c-2cbd-4614-adb6-d92eac707634","content":"<p>will have included</p>"},{"id":"aa41d083-b99c-4114-bcc4-528c76a1046a","content":"<p>had included</p>"}],"keys":["be974064-9eda-4879-be80-06b21f19e9f2"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb &ldquo;includes,&rdquo; used in conjunction with the word &ldquo;currently,&rdquo; correctly indicates that the frog&rsquo;s current range includes parts of northern New South Wales and southeastern Queensland.</p><p>Choice B is incorrect because the past tense verb &ldquo;included&rdquo; doesn&rsquo;t indicate that the frog&rsquo;s range currently includes parts of northern New South Wales and southeastern Queensland. Choice C is incorrect because the future perfect tense &ldquo;will have included&rdquo; doesn&rsquo;t indicate that the frog&rsquo;s range currently includes parts of northern New South Wales and southeastern Queensland. Choice D is incorrect because the past perfect tense &ldquo;had included&rdquo; doesn&rsquo;t indicate that the frog&rsquo;s range currently includes parts of northern New South Wales and southeastern Queensland.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771167,"updateDate":1776362771167}$SATQ$::jsonb, 1776362771167, 1776362771167),
    ($SATQ$04bfd364$SATQ$, $SATQ$06094015-954f-4609-9640-c794948f54c0$SATQ$::uuid, $SATQ$c0ab2718-53d2-4900-854c-5c4b08bc1fff$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The intense pressure found in the deep ocean can affect the structure of proteins in fish&rsquo;s cells, distorting the proteins&rsquo; shape. The chemical trimethylamine N-oxide (TMAO) counters this effect, ensuring that proteins retain their original <span aria-hidden="true">______</span><span class="sr-only">blank</span> is found in high concentrations in the cells of the deepest-dwelling fish.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"574c417b-3733-4b9e-9a00-abb180bc8d11","content":"<p>configurations. TMAO</p>"},{"id":"53262cda-2558-48e1-82ff-e28803689ad4","content":"<p>configurations TMAO</p>"},{"id":"d8a3b952-3ed8-44df-b947-c1b93da1909c","content":"<p>configurations, TMAO</p>"},{"id":"bc225b30-771e-4152-a2d2-ea780bb9d54f","content":"<p>configurations and TMAO</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["574c417b-3733-4b9e-9a00-abb180bc8d11"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;configurations&rdquo; is used correctly to mark the boundary between one sentence (&ldquo;The intense&hellip;configurations&rdquo;) and another (&ldquo;TMAO&hellip;fish&rdquo;). The supplementary phrase (&ldquo;ensuring&hellip;configurations&rdquo;) modifies the main clause of the first sentence (&ldquo;The chemical&hellip;effect&rdquo;), and &ldquo;TMAO&rdquo; is the subject of the second sentence. </p><p>Choice B is incorrect because it results in a run-on sentence. The sentences&nbsp; (&ldquo;The intense&hellip;configurations&rdquo; and &ldquo;TMAO&hellip;fish&rdquo;) are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join sentences. </p>$SATQ$, false, 0, $SATQ$OSP-704-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$55729ae5-4213-4d47-91d0-920ddac40067$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"04bfd364","external_id":"06094015-954f-4609-9640-c794948f54c0","vaultid":"c0ab2718-53d2-4900-854c-5c4b08bc1fff","uId":"7817f876-cd8c-4b92-9574-a3a1809c2182","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The intense pressure found in the deep ocean can affect the structure of proteins in fish&rsquo;s cells, distorting the proteins&rsquo; shape. The chemical trimethylamine N-oxide (TMAO) counters this effect, ensuring that proteins retain their original <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> is found in high concentrations in the cells of the deepest-dwelling fish.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"574c417b-3733-4b9e-9a00-abb180bc8d11","content":"<p>configurations. TMAO</p>"},{"id":"53262cda-2558-48e1-82ff-e28803689ad4","content":"<p>configurations TMAO</p>"},{"id":"d8a3b952-3ed8-44df-b947-c1b93da1909c","content":"<p>configurations, TMAO</p>"},{"id":"bc225b30-771e-4152-a2d2-ea780bb9d54f","content":"<p>configurations and TMAO</p>"}],"keys":["574c417b-3733-4b9e-9a00-abb180bc8d11"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;configurations&rdquo; is used correctly to mark the boundary between one sentence (&ldquo;The intense&hellip;configurations&rdquo;) and another (&ldquo;TMAO&hellip;fish&rdquo;). The supplementary phrase (&ldquo;ensuring&hellip;configurations&rdquo;) modifies the main clause of the first sentence (&ldquo;The chemical&hellip;effect&rdquo;), and &ldquo;TMAO&rdquo; is the subject of the second sentence. </p><p>Choice B is incorrect because it results in a run-on sentence. The sentences&nbsp; (&ldquo;The intense&hellip;configurations&rdquo; and &ldquo;TMAO&hellip;fish&rdquo;) are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join sentences. </p>","parenttemplatename":"OSP-704-SEC","parenttemplateid":"","templateclusterid":"55729ae5-4213-4d47-91d0-920ddac40067","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$083a35dc$SATQ$, $SATQ$26edb161-36c0-40ea-89cd-588e9b2b1f31$SATQ$::uuid, $SATQ$fc81aa32-304e-4fb6-8d6c-b93ca33f6ddb$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Po&rsquo;Pay was a Tewa leader from Ohkay Owingeh, a pueblo located about twenty-five miles north of present-day Santa Fe, New Mexico. He was instrumental in organizing the Pueblo Revolt of <span aria-hidden="true">______</span><span class="sr-only">blank</span> as a result of his leadership, the Spanish colonizers were expelled from the region for a time.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7fc492fa-b2a9-4ec2-8b76-b556f5b0d825","content":"<p>1680</p>"},{"id":"2b4e7807-ef8c-4e09-8ba0-ce0335415d53","content":"<p>1680 and</p>"},{"id":"9569c604-53bc-4729-9a0f-2723ed02e820","content":"<p>1680,</p>"},{"id":"8177baeb-cd45-4999-a043-738292075713","content":"<p>1680, and</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["8177baeb-cd45-4999-a043-738292075713"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction &ldquo;and&rdquo; to join the first main clause (&ldquo;He&hellip;1680&rdquo;) and the second main clause (&ldquo;as&hellip;time&rdquo;). </p><p>Choice A is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice B is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice C is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. </p>$SATQ$, false, 0, $SATQ$OSP-750-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$c483db47-73ba-4350-99d2-8578bb724da3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"083a35dc","external_id":"26edb161-36c0-40ea-89cd-588e9b2b1f31","vaultid":"fc81aa32-304e-4fb6-8d6c-b93ca33f6ddb","uId":"472a8c14-9bb3-47ea-916a-6677c87323f9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Po&rsquo;Pay was a Tewa leader from Ohkay Owingeh, a pueblo located about twenty-five miles north of present-day Santa Fe, New Mexico. He was instrumental in organizing the Pueblo Revolt of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> as a result of his leadership, the Spanish colonizers were expelled from the region for a time.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7fc492fa-b2a9-4ec2-8b76-b556f5b0d825","content":"<p>1680</p>"},{"id":"2b4e7807-ef8c-4e09-8ba0-ce0335415d53","content":"<p>1680 and</p>"},{"id":"9569c604-53bc-4729-9a0f-2723ed02e820","content":"<p>1680,</p>"},{"id":"8177baeb-cd45-4999-a043-738292075713","content":"<p>1680, and</p>"}],"keys":["8177baeb-cd45-4999-a043-738292075713"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction &ldquo;and&rdquo; to join the first main clause (&ldquo;He&hellip;1680&rdquo;) and the second main clause (&ldquo;as&hellip;time&rdquo;). </p><p>Choice A is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice B is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Choice C is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. </p>","parenttemplatename":"OSP-750-SEC","parenttemplateid":"","templateclusterid":"c483db47-73ba-4350-99d2-8578bb724da3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959350,"updateDate":1691007959350}$SATQ$::jsonb, 1691007959350, 1691007959350),
    ($SATQ$0a114526$SATQ$, $SATQ$194d3a74-1fe8-40f1-9cf1-f2ea63dfa463$SATQ$::uuid, $SATQ$7ad0ec02-1860-4667-98e7-b741531f4a82$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In 1937, Chinese American screen actor Anna May Wong, who had portrayed numerous villains and secondary characters but never a heroine, finally got a starring role in Paramount Pictures&rsquo; <em>Daughter of Shanghai</em>, a film that <span aria-hidden="true">______</span><span class="sr-only">blank</span> &ldquo;expanded the range of possibilities for Asian images on screen.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"cfb3da2c-e201-44bc-8f39-db4b16ee8d1c","content":"<p>critic, Stina Chyn, claims</p>"},{"id":"341afd2c-88d2-4b45-bfd0-ebf1bdcdf496","content":"<p>critic, Stina Chyn, claims,</p>"},{"id":"45e23f62-a1fe-43a5-bec3-b7c6b843738c","content":"<p>critic Stina Chyn claims</p>"},{"id":"ca7ce00d-16ed-4d89-ab07-c033d04fe858","content":"<p>critic Stina Chyn, claims,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["45e23f62-a1fe-43a5-bec3-b7c6b843738c"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The conventions being tested are punctuation use between titles and proper nouns and between verbs and integrated quotations. No punctuation is needed to set off the proper noun &ldquo;Stina Chyn&rdquo; from the title that describes Chyn, &ldquo;critic.&rdquo; Because &ldquo;Stina Chyn&rdquo; is essential information identifying the &ldquo;critic,&rdquo; no punctuation is necessary. Further, no punctuation is needed between the verb &ldquo;claims&rdquo; and the following quotation because the quotation is integrated into the structure of the sentence. </p><p>Choice A is incorrect because no punctuation is needed before or after the proper noun &ldquo;Stina Chyn.&rdquo; Setting the critic&rsquo;s name off with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice B is incorrect because no punctuation is needed before or after the proper noun &ldquo;Stina Chyn.&rdquo; Setting the critic&rsquo;s name off with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Additionally, no punctuation is needed between &ldquo;claims&rdquo; and the integrated quotation. Choice D is incorrect because no punctuation is needed between the verb &ldquo;claims&rdquo; and its subject, &ldquo;critic Stina Chyn.&rdquo; Additionally, no punctuation is needed between the verb &ldquo;claims&rdquo; and the integrated quotation. </p>$SATQ$, false, 0, $SATQ$OSP-680-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$e5fedede-b23e-492b-a68a-3d5aa896a62d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0a114526","external_id":"194d3a74-1fe8-40f1-9cf1-f2ea63dfa463","vaultid":"7ad0ec02-1860-4667-98e7-b741531f4a82","uId":"c985b544-14d7-40a4-b0d3-878c844ff306","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In 1937, Chinese American screen actor Anna May Wong, who had portrayed numerous villains and secondary characters but never a heroine, finally got a starring role in Paramount Pictures&rsquo; <em>Daughter of Shanghai</em>, a film that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> &ldquo;expanded the range of possibilities for Asian images on screen.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"cfb3da2c-e201-44bc-8f39-db4